import json
import os

FILENAME = 'expenses.json'

def load_expenses(filename):
    if not os.path.exists(filename):
        return []
    with open(filename, 'r') as f:
        return json.load(f)

def save_expenses(filename, expenses):
    with open(filename, 'w') as f:
        json.dump(expenses, f, indent=2)

def validate_expenses(expenses):
    invalid = []
    for idx, e in enumerate(expenses):
        if not e.get('date'):
            invalid.append((idx, 'missing date'))
        if not e.get('category'):
            invalid.append((idx, 'missing category'))
        if not e.get('description'):
            invalid.append((idx, 'missing description'))
        if e.get('amount', 0) <= 0:
            invalid.append((idx, 'non-positive amount'))
    if not invalid:
        print('all expenses valid')
        return
    print('invalid records:')
    for idx, issue in invalid:
        print(f'  [{idx}] {issue}')
    choice = input('remove all invalid? (y/n): ')
    if choice.lower() == 'y':
        valid = [e for e in expenses if not any(i[0] == idx for idx, i in invalid)]
        save_expenses(FILENAME, valid)
        print('invalid records removed')

def generate_report(expenses, category=None):
    filtered = expenses
    if category:
        filtered = [e for e in expenses if e.get('category') == category]
    return json.dumps(filtered, indent=2)

def main():
    expenses = load_expenses(FILENAME)
    while True:
        cmd = input('command (add/list/summary/save/validate/report/exit): ')
        if cmd == 'exit':
            break
        elif cmd == 'validate':
            validate_expenses(expenses)
        elif cmd == 'report':
            cat = input('category filter (leave blank for all): ')
            report = generate_report(expenses, cat if cat else None)
            print(report)
        else:
            print('not implemented yet')

if __name__ == '__main__':
    main()

