class ExpenseTracker:
    def __init__(self):
        self.expenses = []
    def add_expense(self, category, amount):
        self.expenses.append({"category": category, "amount": float(amount)})
    def get_total(self):
        return sum(e["amount"] for e in self.expenses)
    def get_category_total(self, category):
        return sum(e["amount"] for e in self.expenses if e["category"] == category)

tracker = ExpenseTracker()
tracker.add_expense("Food", 25.50)
print(tracker.get_total())

def category_summary(expenses):
    result = {}
    for e in expenses:
        cat = e['category']
        if cat not in result:
            result[cat] = {'total': 0.0, 'count': 0}
        result[cat]['total'] += e['amount']
        result[cat]['count'] += 1
    return result

def print_category_summary(summary):
    if not summary:
        print('No categories found.')
        return
    print('Category   | Total     | Count')
    print('-' * 25)
    for cat, data in summary.items():
        avg = data['total'] / data['count']
        print(f"{cat} | {data['total']:.2f} | {data['count']} (avg {avg:.2f})")

def search_expenses(expenses, keyword):
    kw = keyword.lower()
    matches = []
    for e in expenses:
        if kw in e['description'].lower() or kw in e['category'].lower():
            matches.append(e)
    return matches

def display_search_results(results):
    if not results:
        print('No matching expenses found.')
        return
    print('Date        | Category | Description   | Amount')
    print('-' * 48)
    for e in results:
        print(f"{e['date']} | {e['category']} | {e['description']} | {e['amount']:.2f}")

def main():
    expenses = []
    while True:
        print('1) Add Expense')
        print('2) View All')
        print('3) Search')
        print('4) Exit')
        choice = input('Select an option: ')
        if choice == '1':
            date = input('Date (YYYY-MM-DD): ')
            category = input('Category: ')
            description = input('Description: ')
            amount = input('Amount: ')
            add_expense(expenses, date, category, description, amount)
        elif choice == '2':
            display_summary(expenses)
        elif choice == '3':
            keyword = input('Enter search keyword: ')
            results = search_expenses(expenses, keyword)
            display_search_results(results)
        elif choice == '4':
            break
        else:
            print('Invalid choice')

