import json
import os

def export_data(expenses, config):
    path = config['data_file']
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(expenses, f, indent=2)

def import_data(config_path):
    if not os.path.exists(config_path):
        return []
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        print('Warning: could not load data file, starting fresh.')
        return []

def main():
    config = {'data_file': 'expenses.json', 'default_budgets': {'Food': 100.0, 'Travel': 200.0}}
    expenses = import_data(config['data_file'])
    budgets = config['default_budgets']
    while True:
        print('1) Add Expense')
        print('2) View All')
        print('3) Search')
        print('4) Exit')
        choice = input('Select an option: ')
        if choice == '1':
            date = input('Date (YYYY-MM-DD): ')
            category = input('Category: ')
            description = input('Description: ')
            amount = input('Amount: ')
            add_expense(expenses, date, category, description, amount)
            export_data(expenses, config)
        elif choice == '2':
            display_summary(expenses)
